  // 匹配源文本中完整的 COT 标签对
  const COT_PAIR_RE = /<([^<>\s/]+_(?:行为逻辑|心里话))\s*>([\s\S]*?)<\/\1>/g;
  const COT_NAME_RE = /^(.*)_(行为逻辑|心里话)$/;
  const KIND_LABEL = {
    行为逻辑: '行为逻辑',
    心里话: '心里话',
  };

  const processedSignatures = new Map();
  const touchedMessageIds = new Set();
  let disposed = false;
  let renderAllTimer;

  // ======== 工具函数 ==========

  function getCurrentScriptId() {
    try {
      return typeof getScriptId === 'function' ? getScriptId() : 'standalone';
    } catch {
      return 'standalone';
    }
  }

  function styleId() {
    return `${NAMESPACE}-style-${String(getCurrentScriptId()).replace(/[^\w-]/g, '_')}`;
  }

  function escapeHtml(text) {
    return String(text).replace(/[&<>"']/g, char => {
      const escapes = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };
      return escapes[char] || char;
    });
  }

  function parseCotTag(tag) {
    const match = String(tag).match(COT_NAME_RE);
    if (!match) return null;
    return { actor: match[1], kind: match[2] };
  }

  function moonSvg() {
    return `<svg class="${NAMESPACE}-moon" width="12" height="12" viewBox="0 0 24" aria-hidden="true" focusable="false" style="display:block;width:12px;height:12px;max-width:12px;max-height:12px;min-width:12px;min-height:12px;overflow:hidden;flex:0 0 12px;"><path class="${NAMESPACE}-moon-fill" d="M14.7 2.2a8.8 8.8 0 1 0 7.1 13.9 7.2 7.2 0 1-7.1-13.9Z" fill="currentColor"/></svg>`;
  }

  function chevronSvg() {
