  // ========== 折叠 HTML 生成 ==========

  /**
   * 为单个 COT 标签对生成折叠卡片 HTML
   */
  function buildFoldHtml(tag, content, mode) {
    const parsed = parseCotTag(tag);
    if (!parsed) return null;

    const actorLabel = escapeHtml(parsed.actor);
    const kindLabel = KIND_LABEL[parsed.kind] || parsed.kind;
