AAiB,MAAO,CAAE,4BAA6B,CAAE,cAAe,CAAE,eAAgB,CAAE,sBAAuB,CAAE,kBAAqB,CAC1I,+BAAgB,aAAc,CAAE,cAAe,CAAE,0BAA6B,CAE9E,iCAAkB,qBAAsB,CAAE,2CAA4C,CAAE,cAAe,CAAE,YAAa,CAAE,qBAAsB,CAAE,OAAU,CAC1J,6BACE,uCAAwC,CACxC,iBAAkB,CAClB,eAAgB,CAChB,gCACF,CACA,mCACE,YAAa,CAAE,kBAAmB,CAAE,OAAQ,CAAE,cAAe,CAC7D,cAAe,CAAE,eAAgB,CAAE,4BAA6B,CAAE,iBACpE,CACA,iCAAkB,cAAe,CAAE,eAAgB,CAAE,0BAA6B,CAClF,iCAAkB,gBAAiB,CAAE,YAAa,CAAE,OAAU,CAC9D,8BACE,UAAW,CAAE,qBAAsB,CACnC,gCAAiC,CACjC,sCAAuC,CACvC,iBAAkB,CAClB,eAAgB,CAAE,cAAe,CAAE,eAAgB,CACnD,4BAA6B,CAAE,eAAgB,CAAE,YAAa,CAC9D,mBAAoB,CACpB,6CACF,CACA,oCAAqB,8BAAiC,CACtD,yBACE,oBAAqB,CAAE,qBAAsB,CAC7C,cAAe,CAAE,eAAgB,CAAE,4BAA6B,CAChE,mBAAoB,CAAE,QACxB,CACA,gCACE,oBAAqB,CAAE,qBAAsB,CAC7C,cAAe,CAAE,eAAgB,CAAE,4BAA6B,CAChE,mBAAoB,CAAE,QAAS,CAAE,gBAAiB,CAAE,eACtD,CACA,yBAAU,+CAAiD,CAAE,iBAAkB,CAAE,eAAgB,CAAE,0CAA8C,CACjJ,kCAAmB,YAAa,CAAE,OAAQ,CAAE,wBAA2B,CAEvE,gCAAiB,gBAAmB,CAGpC,iCACE,YAAa,CAAE,kBAAmB,CAAE,OAAQ,CAC5C,gBAAiB,CAAE,cAAe,CAClC,iBAAkB,CAAE,gCAAiC,CACrD,cAAe,CAAE,4BAA6B,CAC9C,oDACF,CACA,uCAAwB,yCAA6C,CACrE,sCAAuB,0CAA8C,CACrE,sCAAuB,MAAO,CAAE,eAAkB,CAClD,qCAAsB,YAAa,CAAE,OAAU,CAC/C,uCAAwB,aAAc,CAAE,0BAA6B,CAGrE,qCACE,gBAAiB,CACjB,gCAAiC,CACjC,uCAAwC,CACxC,iBAAkB,CAClB,YAAa,CAAE,qBAAsB,CAAE,OACzC,CACA,8BAAe,aAAgB","sourcesContent":["<script setup lang=\"ts\">\n/**\n * 世界书蒸馏 Tab\n * - 顶部：枚举可用世界书（角色卡主/附加 + 全局 + 聊天级），整本或展开选条目，一键蒸馏\n * - 底部：蒸馏结果列表（每条含 worldView + 每角色一节），全部可编辑、可删除\n */\nimport { useMainStore } from '../stores/mainStore';\nimport { ConfirmButton, EmptyHint } from './ui';\nimport { enqueueAnalysis } from '../core/backgroundQueue';\nimport {\n  listAvailableWorldbooks,\n  readWorldbook,\n  executeWorldBookDistill,\n  type WorldbookGroup,\n  type DistillEntry,\n  type DistillRecord,\n} from '../core/worldBookDistill';\n\nconst store = useMainStore();\n\n// ─── 世界书枚举 ───\nconst showSelector = ref(true); // 选择世界书区整块折叠开关\nconst wbGroup = ref<WorldbookGroup>({ char: { primary: null, additional: [] }, charName: '', global: [], chat: null, all: [] });\nconst loadingBooks = ref(false);\nconst expandedBooks = ref<Set<string>>(new Set()); // 已展开看条目的书\nconst entriesByBook = ref<Record<string, DistillEntry[]>>({});\n// 列表加载/展开异常提示（区分\"真空\"与\"出错\"）\nconst booksError = ref('');\nconst expandingBook = ref<string>(''); // 正在展开条目的书名（防重复点击 + 占位）\n\n// ─── 选中状态 ───\n// 选中的书名（整本勾选）\nconst selectedBookNames = ref<Set<string>>(new Set());\n// 每本书里额外勾选的条目名（若该书被整本选，则忽略此集合）\nconst selectedEntriesByBook = ref<Record<string, Set<string>>>({});\n\nasync function refreshBooks() {\n  loadingBooks.value = true;\n  try {\n    wbGroup.value = listAvailableWorldbooks();\n    booksError.value = '';\n  } catch (e) {\n    console.error('[DistillTab] 世界书列表加载失败:', e);\n    booksError.value = '世界书列表加载失败，请重试';\n  } finally {\n    loadingBooks.value = false;\n  }\n}\n\nasync function expandBook(bookName: string) {\n  if (expandedBooks.value.has(bookName)) {\n    expandedBooks.value.delete(bookName);\n    expandedBooks.value = new Set(expandedBooks.value);\n    return;\n  }\n  if (!entriesByBook.value[bookName]) {\n    expandingBook.value = bookName;\n    try {\n      entriesByBook.value[bookName] = await readWorldbook(bookName);\n      booksError.value = '';\n    } catch (e) {\n      console.error('[DistillTab] 展开世界书条目失败:', e);\n      booksError.value = `展开「${bookName}」失败，请重试`;\n      expandingBook.value = '';\n      return;\n    }\n  }\n  expandedBooks.value.add(bookName);\n  expandedBooks.value = new Set(expandedBooks.value);\n  expandingBook.value = '';\n}\n\nfunction toggleBook(bookName: string) {\n  const s = new Set(selectedBookNames.value);\n  if (s.has(bookName)) s.delete(bookName); else s.add(bookName);\n  selectedBookNames.value = s;\n}\n\nfunction toggleEntry(bookName: string, entryName: string) {\n  const cur = new Set(selectedEntriesByBook.value[bookName] || []);\n  if (cur.has(entryName)) cur.delete(entryName); else cur.add(entryName);\n  selectedEntriesByBook.value = { ...selectedEntriesByBook.value, [bookName]: cur };\n}\n\nfunction allBooksAvailable(): string[] {\n  const g = wbGroup.value;\n  const set = new Set<string>([...(g.char?.primary ? [g.char.primary] : []), ...(g.char?.additional || []), ...g.global, ...(g.chat ? [g.chat] : [])]);\n  return [...set];\n}\n\nconst totalSelectedEntries = computed(() => {\n  let n = 0;\n  for (const book of selectedBookNames.value) {\n    if (expandedBooks.value.has(book) && entriesByBook.value[book]) {\n      const picked = selectedEntriesByBook.value[book];\n      if (picked && picked.size > 0) n += picked.size;\n      else n += entriesByBook.value[book].length;\n    } else {\n      // 未展开则视为整本，若还没读到条目则记 0（蒸馏时才精确算）\n      n += (entriesByBook.value[book]?.length || 0);\n    }\n  }\n  return n;\n});\n\n// ─── 蒸馏 ───\nconst distilling = ref(false);\nconst distillError = ref('');\n\nasync function runDistill() {\n  const books = [...selectedBookNames.value];\n  if (books.length === 0) {\n    distillError.value = '请先选择至少一本世界书';\n    return;\n  }\n  distillError.value = '';\n  distilling.value = true;\n\n  // 提取每本书所选条目名（展开且手动勾选了才算子集；否则该书全选）\n  const selectedEntryNamesPerBook: Record<string, string[]> = {};\n  for (const book of books) {\n    const picked = selectedEntriesByBook.value[book];\n    if (picked && picked.size > 0) selectedEntryNamesPerBook[book] = [...picked];\n  }\n\n  const group = wbGroup.value;\n  const sourceCharName = group.charName || undefined;\n\n  enqueueAnalysis('world_book_distill', async () => {\n    try {\n      const record = await executeWorldBookDistill({\n        selectedBookNames: books,\n        selectedEntryNamesPerBook,\n        sourceCharName,\n        userName: store.getUserName(),\n      });\n      store.upsertDistillRecord(record);\n      expandedRecordId.value = record.id;\n      console.info('[智脑-蒸馏] 完成:', record.id);\n    } catch (e: any) {\n      distillError.value = `蒸馏失败: ${e?.message || e}`;\n      console.error('[智脑-蒸馏] 失败', e);\n    } finally {\n      distilling.value = false;\n    }\n  });\n}\n\n// ─── 结果列表 ───\nconst records = computed<DistillRecord[]>(() => store.distillRecords as any);\nconst expandedRecordId = ref<string | null>(null);\n// 第3层：当前展开查看原文的条目 key（格式: recordId + '||' + sectionKey）\nconst expandedSectionKey = ref<string | null>(null);\n\nfunction toggleExpandRecord(id: string) {\n  if (expandedRecordId.value === id) {\n    expandedRecordId.value = null;\n    return;\n  }\n  expandedRecordId.value = id;\n  expandedSectionKey.value = null; // 切换记录时收起第3层\n  const r = (records.value as any).find((x: any) => x.id === id);\n  if (r) ensureCache(r);\n}\n\nfunction toggleSection(recordId: string, sectionKey: string) {\n  const key = recordId + '||' + sectionKey;\n  expandedSectionKey.value = expandedSectionKey.value === key ? null : key;\n}\n\nfunction isSectionOpen(recordId: string, sectionKey: string): boolean {\n  return expandedSectionKey.value === recordId + '||' + sectionKey;\n}\n\nfunction deleteRecord(id: string) {\n  store.removeDistillRecord(id);\n  if (expandedRecordId.value === id) expandedRecordId.value = null;\n}\n\nfunction clearAll() {\n  if (!confirm('清空所有蒸馏结果？此操作不可撤销。')) return;\n  store.clearDistillRecords();\n}\n\n// 本地编辑缓存（避免每次输入都落盘）\nconst editCache = ref<Record<string, { worldText: string; chars: Record<string, string> }>>({});\n\nfunction ensureCache(r: DistillRecord) {\n  if (editCache.value[r.id]) return;\n  const chars: Record<string, string> = {};\n  for (const c of r.characters) chars[c.characterName] = c.text;\n  editCache.value = {\n    ...editCache.value,\n    [r.id]: { worldText: r.worldView.text, chars },\n  };\n}\n\nfunction saveRecordEdits(r: DistillRecord) {\n  const cache = editCache.value[r.id];\n  if (!cache) return;\n  const updated: DistillRecord = {\n    ...r,\n    worldView: { ...r.worldView, text: cache.worldText },\n    characters: r.characters.map(c => ({ ...c, text: cache.chars[c.characterName] ?? c.text })),\n  };\n  store.updateDistillRecord(updated);\n  delete editCache.value[r.id];\n  editCache.value = { ...editCache.value };\n}\n\nfunction renameChar(r: DistillRecord, oldName: string) {\n  const cache = editCache.value[r.id];\n  if (!cache) return;\n  const newName = prompt('新角色名:', oldName);\n  if (!newName || newName === oldName) return;\n  const text = cache.chars[oldName] ?? '';\n  const newChars: Record<string, string> = {};\n  for (const [k, v] of Object.entries(cache.chars)) {\n    if (k === oldName) newChars[newName] = v;\n    else newChars[k] = v;\n  }\n  editCache.value = { ...editCache.value, [r.id]: { ...cache, chars: newChars } };\n\n  const updated: DistillRecord = {\n    ...r,\n    characters: r.characters.map(c => c.characterName === oldName ? { ...c, characterName: newName } : c),\n  };\n  store.updateDistillRecord(updated);\n}\n\nfunction deleteChar(r: DistillRecord, name: string) {\n  const updated: DistillRecord = {\n    ...r,\n    characters: r.characters.filter(c => c.characterName !== name),\n  };\n  store.updateDistillRecord(updated);\n  if (editCache.value[r.id]) {\n    const cache = editCache.value[r.id];\n    delete cache.chars[name];\n    editCache.value = { ...editCache.value };\n  }\n}\n\nfunction fmtTime(ts: number): string {\n  try { return new Date(ts).toLocaleString(); } catch { return ''; }\n}\n\n// 初次进入自动枚举一次\nonMounted(() => { refreshBooks(); });\n</script>\n\n<template>\n  <div class=\"distill-tab\">\n    \x3c!-- 顶部：蒸馏操作区 --\x3e\n    <div class=\"dt-panel\">\n      <div class=\"dt-panel-header\">\n        <span class=\"dt-panel-title\">世界书蒸馏</span>\n        <span class=\"dt-count\">已选 {{ selectedBookNames.size }} 本 / {{ totalSelectedEntries }} 条目</span>\n        <button class=\"dt-btn-xs dt-toggle-btn\" @click=\"showSelector = !showSelector\">\n          {{ showSelector ? '收起选择区' : '展开选择区' }}\n        </button>\n      </div>\n\n      <div v-if=\"showSelector\" class=\"dt-selector-body\">\n      <div class=\"dt-desc\">\n        选中世界书后一键蒸馏。AI 只做<b>原文提取归类</b>（每角色一条 + 世界观一块），逐字保留、不改写。结果可编辑、跨聊天复用。\n      </div>\n\n      \x3c!-- 世界书选择：分组渲染 --\x3e\n      <div class=\"dt-wb-groups\">\n        \x3c!-- 角色卡世界书 --\x3e\n        <div v-if=\"wbGroup.char.primary || wbGroup.char.additional.length\" class=\"dt-wb-group\">\n          <div class=\"dt-wb-group-label\">角色卡世界书{{ wbGroup.charName ? `（${wbGroup.charName}）` : '' }}</div>\n          <label v-if=\"wbGroup.char.primary\" class=\"dt-wb-book\">\n            <input type=\"checkbox\" :checked=\"selectedBookNames.has(wbGroup.char.primary)\" @change=\"toggleBook(wbGroup.char.primary)\" />\n            <span class=\"dt-wb-book-name\">{{ wbGroup.char.primary }}（主）</span>\n            <button class=\"dt-wb-expand-btn\" :disabled=\"expandingBook === wbGroup.char.primary\" @click.prevent=\"expandBook(wbGroup.char.primary)\">{{ expandingBook === wbGroup.char.primary ? '加载…' : expandedBooks.has(wbGroup.char.primary) ? '收起' : '展开条目' }}</button>\n          </label>\n          <label v-for=\"b in wbGroup.char.additional\" :key=\"'c_'+b\" class=\"dt-wb-book\">\n            <input type=\"checkbox\" :checked=\"selectedBookNames.has(b)\" @change=\"toggleBook(b)\" />\n            <span class=\"dt-wb-book-name\">{{ b }}（附加）</span>\n            <button class=\"dt-wb-expand-btn\" :disabled=\"expandingBook === b\" @click.prevent=\"expandBook(b)\">{{ expandingBook === b ? '加载…' : expandedBooks.has(b) ? '收起' : '展开条目' }}</button>\n          </label>\n        </div>\n\n        \x3c!-- 全局世界书 --\x3e\n        <div v-if=\"wbGroup.global.length\" class=\"dt-wb-group\">\n          <div class=\"dt-wb-group-label\">全局世界书</div>\n          <label v-for=\"b in wbGroup.global\" :key=\"'g_'+b\" class=\"dt-wb-book\">\n            <input type=\"checkbox\" :checked=\"selectedBookNames.has(b)\" @change=\"toggleBook(b)\" />\n            <span class=\"dt-wb-book-name\">{{ b }}</span>\n            <button class=\"dt-wb-expand-btn\" :disabled=\"expandingBook === b\" @click.prevent=\"expandBook(b)\">{{ expandingBook === b ? '加载…' : expandedBooks.has(b) ? '收起' : '展开条目' }}</button>\n          </label>\n        </div>\n\n        \x3c!-- 聊天级世界书 --\x3e\n        <div v-if=\"wbGroup.chat\" class=\"dt-wb-group\">\n          <div class=\"dt-wb-group-label\">聊天级世界书</div>\n          <label class=\"dt-wb-book\">\n            <input type=\"checkbox\" :checked=\"selectedBookNames.has(wbGroup.chat!)\" @change=\"toggleBook(wbGroup.chat!)\" />\n            <span class=\"dt-wb-book-name\">{{ wbGroup.chat }}</span>\n            <button class=\"dt-wb-expand-btn\" :disabled=\"expandingBook === wbGroup.chat!\" @click.prevent=\"expandBook(wbGroup.chat!)\">{{ expandingBook === wbGroup.chat! ? '加载…' : expandedBooks.has(wbGroup.chat!) ? '收起' : '展开条目' }}</button>\n          </label>\n        </div>\n\n        <EmptyHint v-if=\"!wbGroup.char.primary && !wbGroup.char.additional.length && !wbGroup.global.length && !wbGroup.chat\" text=\"未发现可用世界书。请确认酒馆助手已启用世界书相关功能，且当前角色卡/全局挂载了世界书。\" />\n      </div>\n\n      \x3c!-- 展开的条目列表（所有已展开的书） --\x3e\n      <template v-for=\"book in [...expandedBooks]\" :key=\"'entries_'+book\">\n        <div class=\"dt-wb-entries\">\n          <div class=\"dt-wb-entries-title\">{{ book }} 的条目（勾选要蒸馏的，留空=全部）</div>\n          <EmptyHint v-if=\"(entriesByBook[book] || []).length === 0\" text=\"无启用条目\" />\n          <label v-for=\"e in entriesByBook[book] || []\" :key=\"book+'_'+e.name\" class=\"dt-wb-entry\">\n            <input type=\"checkbox\" :checked=\"(selectedEntriesByBook[book] || new Set()).has(e.name)\" @change=\"toggleEntry(book, e.name)\" />\n            <span>{{ e.name }}</span>\n            <span v-if=\"e.keys.length\" class=\"dt-wb-entry-keys\">{{ e.keys.join('、') }}</span>\n          </label>\n        </div>\n      </template>\n\n      \x3c!-- 操作按钮 --\x3e\n      <div class=\"dt-actions\">\n        <button class=\"dt-btn-primary\" @click=\"runDistill\" :disabled=\"distilling || selectedBookNames.size === 0\">\n          {{ distilling ? '蒸馏中…' : '开始蒸馏' }}\n        </button>\n        <button class=\"dt-btn-xs\" :disabled=\"loadingBooks\" @click=\"refreshBooks\">{{ loadingBooks ? '加载中…' : '刷新世界书列表' }}</button>\n      </div>\n      <div v-if=\"distillError\" class=\"dt-error\">{{ distillError }}</div>\n      <div v-if=\"booksError\" class=\"dt-error\">{{ booksError }}</div>\n      </div>\x3c!-- /dt-selector-body --\x3e\n    </div>\n\n    \x3c!-- 底部：蒸馏结果列表 --\x3e\n    <div class=\"dt-panel\" style=\"flex:1;min-height:0;display:flex;flex-direction:column\">\n      <div class=\"dt-panel-header\">\n        <span class=\"dt-panel-title\">蒸馏结果</span>\n        <span>\n          <span class=\"dt-count\">{{ records.length }} 条</span>\n          <button v-if=\"records.length\" class=\"dt-btn-xs dt-btn-danger\" style=\"margin-left:8px\" @click=\"clearAll\">清空</button>\n        </span>\n      </div>\n\n      <EmptyHint v-if=\"records.length === 0\" text=\"暂无蒸馏结果。选好世界书后点「开始蒸馏」。\" />\n\n      <div v-else class=\"dt-list\">\n        <div v-for=\"r in records\" :key=\"r.id\" class=\"dt-item\" :class=\"{ expanded: expandedRecordId === r.id }\">\n          <div class=\"dt-item-header\" @click=\"toggleExpandRecord(r.id)\">\n            <span class=\"dt-item-badge\" :class=\"r.status\">{{ r.status === 'ready' ? '就绪' : '失败' }}</span>\n            <span class=\"dt-item-title\">{{ r.sourceBookNames.join('、') }}</span>\n            <span class=\"dt-item-meta\">{{ r.characters.length }} 角色 · {{ fmtTime(r.distillAt) }}</span>\n            <ConfirmButton class=\"dt-item-del\" @click.stop @confirm=\"deleteRecord(r.id)\" />\n          </div>\n\n          <div v-if=\"expandedRecordId === r.id\" class=\"dt-item-detail\">\n            \x3c!-- 第2层：条目名列表（点击进入第3层看原文） --\x3e\n\n            \x3c!-- 世界观条目行 --\x3e\n            <div\n              v-if=\"r.worldView.text || r.worldView.sourceEntries.length\"\n              class=\"dt-section-row\"\n              :class=\"{ open: isSectionOpen(r.id, '__worldView__') }\"\n              @click=\"toggleSection(r.id, '__worldView__')\"\n            >\n              <span class=\"dt-section-row-name\">🌍 世界观（{{ r.worldView.sourceEntries.length }} 条）</span>\n              <span class=\"dt-section-row-arrow\">{{ isSectionOpen(r.id, '__worldView__') ? '▲' : '▼' }}</span>\n            </div>\n            <div v-if=\"isSectionOpen(r.id, '__worldView__')\" class=\"dt-section-content\">\n              <div class=\"dt-section-src\">来源: {{ r.worldView.sourceEntries.join('、') || '无' }}</div>\n              <textarea\n                v-if=\"editCache[r.id]\"\n                class=\"dt-textarea\"\n                v-model=\"editCache[r.id].worldText\"\n                rows=\"8\"\n                placeholder=\"（无世界观条目）\"\n              />\n              <pre v-else class=\"dt-pre\">{{ r.worldView.text || '（无）' }}</pre>\n            </div>\n\n            \x3c!-- 角色条目行 --\x3e\n            <template v-for=\"c in r.characters\" :key=\"r.id+'_'+c.characterName\">\n              <div\n                class=\"dt-section-row\"\n                :class=\"{ open: isSectionOpen(r.id, c.characterName) }\"\n                @click=\"toggleSection(r.id, c.characterName)\"\n              >\n                <span class=\"dt-section-row-name\">👤 {{ c.characterName }}（{{ c.sourceEntries.length }} 条）</span>\n                <span class=\"dt-section-row-ops\">\n                  <button class=\"dt-btn-xs\" @click.stop=\"renameChar(r, c.characterName)\">改名</button>\n                  <ConfirmButton @click.stop @confirm=\"deleteChar(r, c.characterName)\" />\n                </span>\n                <span class=\"dt-section-row-arrow\">{{ isSectionOpen(r.id, c.characterName) ? '▲' : '▼' }}</span>\n              </div>\n              <div v-if=\"isSectionOpen(r.id, c.characterName)\" class=\"dt-section-content\">\n                <div class=\"dt-section-src\">来源: {{ c.sourceEntries.join('、') || '无' }}</div>\n                <textarea\n                  v-if=\"editCache[r.id]\"\n                  class=\"dt-textarea\"\n                  v-model=\"editCache[r.id].chars[c.characterName]\"\n                  rows=\"8\"\n                />\n                <pre v-else class=\"dt-pre\">{{ c.text || '（无）' }}</pre>\n              </div>\n            </template>\n\n            <div v-if=\"r.status === 'failed' && r.error\" class=\"dt-raw\">\n              <div class=\"dt-section-label\">⚠ 失败原因:</div>\n              <pre class=\"dt-pre dt-pre-scroll\">{{ r.error }}</pre>\n            </div>\n\n            <div v-if=\"r.status === 'failed' && r.rawJson\" class=\"dt-raw\">\n              <div class=\"dt-section-label\">⚠ 解析失败原始输出:</div>\n              <pre class=\"dt-pre dt-pre-scroll\">{{ r.rawJson }}</pre>\n            </div>\n\n            <div class=\"dt-item-actions\">\n              <button class=\"dt-btn-xs dt-btn-save\" @click=\"saveRecordEdits(r)\">保存编辑</button>\n            </div>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n</template>\n\n<style scoped>\n.distill-tab {\n  flex: 1;\n  min-height: 0;\n  display: flex;\n  flex-direction: column;\n  overflow: hidden;\n  gap: 8px;\n  padding: 10px 12px;\n}\n.dt-panel {\n  background: var(--zn-bg-surface1);\n  border: 1px solid var(--zn-border-light);\n  border-radius: 8px;\n  padding: 10px;\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n}\n.dt-panel-header {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n}\n.dt-panel-title { font-size: 12px; font-weight: 600; color: var(--zn-text-regular); letter-spacing: 0.5px; }\n.dt-count { font-size: 11px; color: rgba(var(--zn-accent-rgb), 0.7); }\n.dt-desc { font-size: 11px; color: var(--zn-text-muted); line-height: 1.6; }\n.dt-placeholder {\n  font-size: 12px; color: var(--zn-text-muted); line-height: 1.6;\n  padding: 12px; background: var(--zn-bg-surface1); border-radius: 6px;\n  border: 1px dashed var(--zn-border-light);\n}\n.dt-error { font-size: 11px; color: rgba(var(--zn-danger-rgb), 0.85); }\n\n.dt-wb-groups { display: flex; flex-direction: column; gap: 8px; }\n.dt-wb-group {\n  border-left: 2px solid rgba(var(--zn-accent-rgb), 0.2);\n  padding-left: 8px;\n  display: flex; flex-direction: column; gap: 2px;\n}\n.dt-wb-group-label { font-size: 11px; font-weight: 600; color: var(--zn-text-regular); margin-bottom: 2px; }\n.dt-wb-book {\n  display: flex; align-items: center; gap: 6px;\n  font-size: 11px; color: var(--zn-text-regular);\n  padding: 3px 0; cursor: pointer;\n}\n.dt-wb-book input[type=\"checkbox\"] { accent-color: rgba(var(--zn-accent-rgb), 0.8); }\n.dt-wb-book-name { flex: 1; }\n.dt-wb-expand-btn {\n  font-size: 10px; padding: 1px 6px; border-radius: 4px;\n  border: 1px solid var(--zn-border-base); background: var(--zn-bg-surface1);\n  color: var(--zn-text-muted); cursor: pointer;\n  transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);\n}\n.dt-wb-expand-btn:hover { color: rgba(var(--zn-accent-rgb), 0.85); }\n\n.dt-wb-entries {\n  background: var(--zn-bg-surface1);\n  border: 1px solid var(--zn-border-light);\n  border-radius: 6px;\n  padding: 6px 8px;\n  max-height: 200px;\n  overflow-y: auto;\n}\n.dt-wb-entries-title { font-size: 10px; color: rgba(var(--zn-accent-rgb), 0.7); margin-bottom: 4px; }\n.dt-wb-entry {\n  display: flex; align-items: center; gap: 6px;\n  font-size: 11px; color: var(--zn-text-regular);\n  padding: 2px 0; cursor: pointer;\n}\n.dt-wb-entry input[type=\"checkbox\"] { accent-color: rgba(var(--zn-accent-rgb), 0.8); }\n.dt-wb-entry-keys { font-size: 10px; color: var(--zn-text-muted); margin-left: auto; }\n\n.dt-actions { display: flex; gap: 8px; align-items: center; }\n.dt-btn-primary {\n  padding: 5px 14px; font-size: 11px; font-weight: 600; border-radius: 4px;\n  border: 1px solid rgba(var(--zn-accent-rgb), 0.3); background: rgba(var(--zn-accent-rgb), 0.12);\n  color: rgba(var(--zn-accent-rgb), 0.9); cursor: pointer; transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);\n}\n.dt-btn-primary:hover:not(:disabled) { background: rgba(var(--zn-accent-rgb), 0.22); }\n.dt-btn-primary:disabled { opacity: 0.4; cursor: not-allowed; }\n.dt-btn-xs {\n  padding: 