中提取。\" />\n\n    <div v-else class=\"wt-list\">\n      <div v-for=\"(item, idx) in itemMemories\" :key=\"idx\" class=\"wt-item\">\n        \x3c!-- 查看模式 --\x3e\n        <div v-if=\"editingItemIdx !== idx\" class=\"wt-item-header\">\n          <span class=\"wt-item-name\">{{ item.itemName }}</span>\n          <span class=\"wt-item-desc\">{{ item.description || '-' }}</span>\n          <span class=\"wt-item-owner\">{{ item.currentOwner || '-' }}</span>\n          <span class=\"wt-item-state\">{{ item.currentState || '正常' }}</span>\n          <span class=\"wt-item-source\">{{ getItemSource(item) || '-' }}</span>\n          <button class=\"wt-btn-xs\" @click=\"startEditItem(idx)\">编辑</button>\n          <ConfirmButton @confirm=\"removeItem(idx)\" />\n        </div>\n        \x3c!-- 编辑模式 --\x3e\n        <div v-else class=\"wt-item-edit\">\n          <div class=\"wt-edit-row\">\n            <span class=\"wt-edit-label\">名称</span>\n            <input v-model=\"editItemName\" class=\"wt-edit-input\" />\n          </div>\n          <div class=\"wt-edit-row\">\n            <span class=\"wt-edit-label\">描述</span>\n            <input v-model=\"editItemDesc\" class=\"wt-edit-input\" />\n          </div>\n          <div class=\"wt-edit-row\">\n            <span class=\"wt-edit-label\">持有者</span>\n            <input v-model=\"editItemOwner\" class=\"wt-edit-input\" />\n          </div>\n          <div class=\"wt-edit-row\">\n            <span class=\"wt-edit-label\">状态</span>\n            <input v-model=\"editItemState\" class=\"wt-edit-input\" />\n          </div>\n          <div class=\"wt-edit-row\">\n            <span class=\"wt-edit-label\">来源</span>\n            <input v-model=\"editItemSource\" class=\"wt-edit-input\" />\n          </div>\n          <div class=\"wt-edit-actions\">\n            <button class=\"wt-btn-xs-save\" @click=\"saveEditItem\">保存</button>\n            <button class=\"wt-btn-xs\" @click=\"cancelEditItem\">取消</button>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { useMainStore } from '../stores/mainStore';\nimport { ConfirmButton, EmptyHint } from './ui';\nimport type { ItemMemory } from '../core/itemMemory';\nimport { invalidateItemEmbedding } from '../core/itemMemory';\n\nconst store = useMainStore();\n\n// ═══════════════════════════════════════\n// 物品记忆面板\n// ═══════════════════════════════════════\n\nconst itemMemories = computed(() => (store.chatData.itemMemories || []) as ItemMemory[]);\n\n/** 获取物品的最新来源事件（从历史记录取最后一条的 event） */\nfunction getItemSource(item: ItemMemory): string {\n  const latest = item.history?.[item.history.length - 1];\n  return latest?.event || '';\n}\n\nfunction removeItem(idx: number) {\n  store.chatData.itemMemories.splice(idx, 1);\n  store.forcePersist();\n}\n\n// 物品编辑状态\nconst editingItemIdx = ref(-1);\nconst editItemName = ref('');\nconst editItemDesc = ref('');\nconst editItemOwner = ref('');\nconst editItemState = ref('');\nconst editItemSource = ref('');\n\nfunction startEditItem(idx: number) {\n  const item = store.chatData.itemMemories[idx];\n  if (!item) return;\n  editingItemIdx.value = idx;\n  editItemName.value = item.itemName || '';\n  editItemDesc.value = item.description || '';\n  editItemOwner.value = item.currentOwner || '';\n  editItemState.value = item.currentState || '';\n  editItemSource.value = getItemSource(item);\n}\n\nfunction saveEditItem() {\n  const idx = editingItemIdx.value;\n  if (idx < 0) return;\n  const items = store.chatData.itemMemories;\n  if (!items[idx]) return;\n  const item = items[idx];\n\n  item.itemName = editItemName.value.trim();\n  item.description = editItemDesc.value.trim();\n  item.currentOwner = editItemOwner.value.trim();\n  item.currentState = editItemState.value.trim() || '正常';\n\n  // 更新来源事件（写入 history 最后一条）\n  const source = editItemSource.value.trim();\n  if (source) {\n    if (item.history.length > 0) {\n      item.history[item.history.length - 1].event = source;\n    } else {\n      item.history.push({ storyTime: '', event: source });\n    }\n  }\n\n  item.lastUpdatedAt = new Date().toISOString();\n  // 编辑后清空向量，下次大总结时重新生成\n  invalidateItemEmbedding(item);\n  store.chatData.itemMemories = [...items];\n  store.forcePersist();\n  editingItemIdx.value = -1;\n}\n\nfunction cancelEditItem() {\n  editingItemIdx.value = -1;\n}\n</script>\n\n<style scoped>\n/* 通用面板 */\n.wt-panel {\n  flex: 1;\n  min-height: 0;\n  overflow-y: auto;\n  padding: 10px 12px;\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n}\n.wt-panel-header {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n}\n.wt-panel-title {\n  font-size: 12px;\n  font-weight: 600;\n  color: var(--zn-text-regular);\n}\n.wt-count {\n  font-size: 11px;\n  color: rgba(var(--zn-accent-rgb), 0.7);\n}\n.wt-placeholder {\n  font-size: 12px;\n  color: var(--zn-text-muted);\n  line-height: 1.6;\n  padding: 12px;\n  background: var(--zn-bg-surface1);\n  border-radius: 6px;\n  border: 1px dashed var(--zn-border-light);\n}\n\n/* 列表 */\n.wt-list {\n  flex: 1;\n  min-height: 0;\n  overflow-y: auto;\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n}\n.wt-item {\n  border: 1px solid var(--zn-border-light);\n  border-radius: 6px;\n  background: var(--zn-bg-surface1);\n  transition: border-color 0.2s cubic-bezier(0.4, 0, 0.2, 1);\n}\n\n.wt-item-header {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  padding: 7px 10px;\n  cursor: pointer;\n  font-size: 12px;\n}\n.wt-item-header:hover { background: var(--zn-bg-surface2); }\n\n/* 物品库专用样式（固定列宽对齐） */\n.wt-item-name {\n  width: 110px;\n  flex-shrink: 0;\n  color: rgba(var(--zn-accent-rgb), 0.9);\n  font-weight: 600;\n  font-size: 11px;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n.wt-item-desc {\n  width: 190px;\n  flex-shrink: 0;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n  color: var(--zn-text-muted);\n  font-size: 11px;\n}\n.wt-item-owner {\n  width: 72px;\n  flex-shrink: 0;\n  color: rgba(var(--zn-success-rgb), 0.7);\n  font-size: 10px;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n.wt-item-state {\n  width: 48px;\n  flex-shrink: 0;\n  font-size: 10px;\n  padding: 1px 6px;\n  border-radius: 8px;\n  background: var(--zn-bg-surface2);\n  color: var(--zn-text-muted);\n  text-align: center;\n}\n.wt-item-source {\n  flex: 1;\n  min-width: 100px;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n  color: var(--zn-text-muted);\n  font-size: 10px;\n}\n\n/* 物品编辑模式 */\n.wt-item-edit {\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n  padding: 8px 10px;\n}\n.wt-edit-row {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n}\n.wt-edit-label {\n  flex-shrink: 0;\n  width: 42px;\n  font-size: 10px;\n  color: var(--zn-text-muted);\n}\n.wt-edit-input {\n  flex: 1;\n  background: var(--zn-bg-surface1);\n  border: 1px solid var(--zn-border-base);\n  border-radius: 4px;\n  color: var(--zn-text-regular);\n  font-size: 11px;\n  padding: 3px 6px;\n  outline: none;\n  transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);\n}\n.wt-edit-input:focus {\n  border-color: var(--zn-primary);\n}\n.wt-edit-actions {\n  display: flex;\n  gap: 8px;\n  margin-top: 6px;\n}\n\n.wt-btn-xs {\n  padding: 2px 6px;\n  font-size: 10px;\n  border-radius: 4px;\n  border: 1px solid var(--zn-border-base);\n  background: var(--zn-bg-surface1);\n  color: var(--zn-text-muted);\n  cursor: pointer;\n  transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);\n}\n.wt-btn-xs:hover { color: var(--zn-text-primary); }\n.wt-btn-xs-save {\n  padding: 2px 6px;\n  font-size: 10px;\n  border-radius: 4px;\n  border: 1px solid rgba(var(--zn-success-rgb), 0.2);\n  background: rgba(var(--zn-success-rgb), 0.08);\n  color: rgba(var(--zn-success-rgb), 0.8);\n  cursor: pointer;\n  transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);\n}\n.wt-btn-xs-save:hover { background: rgba(var(--zn-success-rgb), 0.15); }\n.wt-btn-xs-danger {\n  padding: 2px 6px;\n  font-size: 10px;\n  border-radius: 4px;\n  border: 1px solid rgba(var(--zn-danger-rgb), 0.2);\n  background: transparent;\n  color: rgba(var(--zn-danger-rgb), 0.7);\n  cursor: pointer;\n  transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);\n}\n</style>\n"],"sourceRoot":""}]);
