`, "",{"version":3,"sources":["webpack://./src/components/SmallSummaryPanel.vue"],"names":[],"mappings":"AA8UA,2BACE,MAAO,CACP,YAAa,CACb,eAAgB,CAChB,iBAAkB,CAClB,YAAa,CACb,qBAAsB,CACtB,OACF,CACA,kCACE,YAAa,CACb,kBAAmB,CACnB,6BACF,CACA,iCACE,cAAe,CACf,eAAgB,CAChB,4BACF,CACA,2BACE,cAAe,CACf,oCACF,CACA,iCACE,cAAe,CACf,0BAA2B,CAC3B,eAAgB,CAChB,YAAa,CACb,gCAAiC,CACjC,iBAAkB,CAClB,wCACF,CAGA,gCACE,YAAa,CACb,kBAAmB,CACnB,sBAAuB,CACvB,QAAS,CACT,aAAc,CACd,aACF,CACA,8BACE,gBAAiB,CACjB,cAAe,CACf,iBAAkB,CAClB,+CAAiD,CACjD,0CAA4C,CAC5C,oCAAsC,CACtC,cAAe,CACf,6CACF,CACA,uCAAwB,WAAY,CAAE,kBAAqB,CAC3D,+BAAgB,cAAe,CAAE,0BAA6B,CAG9D,0BACE,MAAO,CACP,YAAa,CACb,eAAgB,CAChB,YAAa,CACb,qBAAsB,CACtB,OACF,CACA,0BACE,uCAAwC,CACxC,iBAAkB,CAClB,gCAAiC,CACjC,sDACF,CACA,mCAAoB,2CAA+C,CACnE,2CAA4B,oDAAwD,CACpF,0CAA2B,qDAAyD,CAEpF,iCACE,YAAa,CACb,kBAAmB,CACnB,OAAQ,CACR,gBAAiB,CACjB,cAAe,CACf,cACF,CACA,uCAAwB,gCAAmC,CAC3D,gCACE,aAAc,CACd,oCAAsC,CACtC,eAAgB,CAChB,cAAe,CACf,cACF,CACA,gCACE,aAAc,CACd,cAAe,CACf,eAAgB,CAChB,iBAAkB,CAClB,gCAAiC,CACjC,0BACF,CACA,sCAAuB,qCAAuC,CAAE,2CAA+C,CAC/G,uCAAwB,oCAAsC,CAAE,0CAA8C,CAC9G,wCAAyB,kCAAoC,CAAE,wCAA4C,CAC3G,gCACE,MAAO,CACP,WAAY,CACZ,eAAgB,CAChB,sBAAuB,CACvB,kBAAmB,CACnB,4BACF,CACA,gCACE,aAAc,CACd,cAAe,CACf,oCAAsC,CACtC,eAAgB,CAChB,eAAgB,CAChB,sBAAuB,CACvB,kBACF,CAGA,iCACE,qBAAsB,CACtB,2CAA4C,CAC5C,cACF,CACA,gCACE,YAAa,CACb,OAAQ,CACR,iBAAkB,CAClB,4BACF,CACA,kCACE,0BAA2B,CAC3B,aAAc,CACd,cACF,CAEA,+BAAgB,cAAiB,CACjC,8BACE,UAAW,CACX,gCAAiC,CACjC,sCAAuC,CACvC,iBAAkB,CAClB,eAAgB,CAChB,cAAe,CACf,4BAA6B,CAC7B,eAAgB,CAChB,YAAa,CACb,cAAe,CACf,6CACF,CACA,oCAAqB,8BAAiC,CAEtD,kCACE,MAAO,CACP,eAAgB,CAChB,cAAe,CACf,iBAAkB,CAClB,sCAAuC,CACvC,gCAAiC,CACjC,4BAA6B,CAC7B,YAAa,CACb,6CACF,CACA,wCAAyB,8BAAiC,CAE1D,kCAAmB,YAAa,CAAE,OAAQ,CAAE,cAAiB,CAC7D,8BACE,gBAAiB,CACjB,cAAe,CACf,iBAAkB,CAClB,gDAAkD,CAClD,2CAA6C,CAC7C,qCAAuC,CACvC,cAAe,CACf,6CACF,CACA,+BACE,gBAAiB,CACjB,cAAe,CACf,iBAAkB,CAClB,6CAA+C,CAC/C,wCAA0C,CAC1C,kCAAoC,CACpC,cAAe,CACf,6CACF,CAEA,2BACE,cAAe,CACf,eAAgB,CAChB,cAAe,CACf,oCAAsC,CACtC,0CAA4C,CAC5C,iBAAkB,CAClB,gDACF,CAGA,gCACE,YAAa,CACb,kBAAmB,CACnB,OAAQ,CACR,aAAc,CACd,iBAAkB,CAClB,+CAAgD,CAChD,cACF,CACA,kCACE,cAAe,CACf,4BAA6B,CAC7B,kBACF,CACA,kCACE,UAAW,CACX,aACF,CACA,iCACE,cAAe,CACf,0BAA2B,CAC3B,kBACF,CAGA,gCACE,aAAc,CACd,gBAAiB,CACjB,eAAgB,CAChB,cACF,CACA,yCACE,WAAY,CACZ,kBACF","sourcesContent":["<template>\n  <div class=\"wt-panel\">\n    <div class=\"wt-panel-header\">\n      <span class=\"wt-panel-title\">小总结记录</span>\n      <span class=\"wt-count\">{{ allSummaries.length }} 条</span>\n      <button\n        class=\"wt-btn-save\"\n        style=\"margin-left:auto\"\n        :disabled=\"floorZeroGenerating\"\n        @click=\"generateFloorZeroSummary\"\n      >{{ floorZeroGenerating ? '生成中...' : hasFloorZeroSummary ? '重新生成开场白' : '为开场白生成' }}</button>\n    </div>\n\n    \x3c!-- 手动补总结：输入 AI 楼层号，自动配对 user=ai-1，总结单轮（两层） --\x3e\n    <div class=\"wt-manual-row\">\n      <span class=\"wt-manual-label\">补总结 AI楼层</span>\n      <input\n        v-model.number=\"manualAiFloor\"\n        class=\"wt-input-inline wt-manual-input\"\n        type=\"number\"\n        min=\"1\"\n        step=\"1\"\n        placeholder=\"如 12\"\n        :disabled=\"manualBusy\"\n      />\n      <button\n        class=\"wt-btn-save\"\n        :disabled=\"manualBusy || manualAiFloor == null\"\n        @click=\"generateManualSummary\"\n      >{{ manualBusy ? '生成中...' : '补总结' }}</button>\n      <span class=\"wt-manual-hint\">输入某轮的 AI 楼层号，将总结该轮（用户+AI 两层）</span>\n    </div>\n\n    <div v-if=\"allSummaries.length === 0\" class=\"wt-placeholder\">\n      暂无小总结记录。AI 回复后将自动生成每轮摘要。\n    </div>\n\n    <template v-else>\n      <div class=\"wt-pagination\">\n        <button class=\"wt-page-btn\" :disabled=\"currentPage === 0\" @click=\"prevPage\">上一页</button>\n        <span class=\"wt-page-info\">{{ currentPage + 1 }} / {{ totalPages }}</span>\n        <button class=\"wt-page-btn\" :disabled=\"currentPage >= totalPages - 1\" @click=\"nextPage\">下一页</button>\n      </div>\n\n      <div class=\"wt-list\">\n        <div\n          v-for=\"s in pagedSummaries\"\n          :key=\"s.id\"\n          class=\"wt-item\"\n          :class=\"['wt-status-' + s.status, { expanded: expandedId === s.id }]\"\n        >\n          <div class=\"wt-item-header\" @click=\"toggleExpand(s)\">\n            <span class=\"wt-item-floor\">{{ floorRangeText(s) }}</span>\n            <span class=\"wt-item-badge\" :class=\"s.status\">{{ statusLabel(s.status) }}</span>\n            <span class=\"wt-item-event\">{{ s.mainEvent || '—' }}</span>\n            <span class=\"wt-item-chars\">{{ (s.presentCharacters || []).join(', ') }}</span>\n            <button\n              class=\"wt-btn-retry wt-btn-inline\"\n              :title=\"retryingIds.has(s.id) ? '正在总结中...' : '用当前聊天记录里的最新正文重新生成该轮小总结'\"\n              :disabled=\"retryingIds.has(s.id)\"\n              @click.stop=\"retrySmallSummary(s)\"\n            >{{ retryingIds.has(s.id) ? '总结中...' : '重新总结' }}</button>\n          </div>\n\n          <div v-if=\"expandedId === s.id\" class=\"wt-item-detail\">\n            <div class=\"wt-detail-row\">\n              <span class=\"wt-detail-label\">时间:</span>\n              <input v-model=\"editingTime\" class=\"wt-input-inline\" placeholder=\"未提及\" />\n            </div>\n            <div class=\"wt-detail-row\">\n              <span class=\"wt-detail-label\">地点:</span>\n              <input v-model=\"editingLocation\" class=\"wt-input-inline\" placeholder=\"未提及\" />\n            </div>\n            <div class=\"wt-detail-row\">\n              <span class=\"wt-detail-label\">在场:</span>\n              <input v-model=\"editingChars\" class=\"wt-input-inline\" placeholder=\"无\" />\n            </div>\n            <div class=\"wt-edit-area\">\n              <label class=\"wt-detail-label\">事件摘要:</label>\n              <textarea v-model=\"editingText\" class=\"wt-textarea\" rows=\"3\"></textarea>\n              <div class=\"wt-edit-actions\">\n                <button class=\"wt-btn-save\" @click=\"saveEdit(s)\">保存</button>\n              </div>\n            </div>\n            <div v-if=\"s.error\" class=\"wt-error\">{{ s.error }}</div>\n          </div>\n        </div>\n      </div>\n    </template>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { useMainStore, type SmallSummaryRecord } from '../stores/mainStore';\nimport { executeSmallSummary } from '../core/smallSummary';\nimport { enqueueAnalysis } from '../core/backgroundQueue';\nimport { extractContentFromMessage } from '../utils/messageParser';\n// @ts-ignore - SillyTavern 全局函数\ndeclare const getChatMessages: (id: number, opt?: { role?: string }) => any[] | null;\n// @ts-ignore - SillyTavern 全局对象\ndeclare const SillyTavern: any;\n\nconst store = useMainStore();\n\n// ═══════════════════════════════════════\n// 小总结公共辅助\n// ═══════════════════════════════════════\n\n/**\n * 将 smallSummaries 按 floorRange.start / end 升序整体排序（原地）。\n * 各消费方本就各自排序，此处仅保证可视列表稳定按楼层序展示。\n */\nfunction sortSmallSummaries() {\n  const arr = store.chatData.smallSummaries;\n  if (!Array.isArray(arr)) return;\n  arr.sort((a: any, b: any) => {\n    const sa = a.floorRange?.start ?? 0;\n    const sb = b.floorRange?.start ?? 0;\n    if (sa !== sb) return sa - sb;\n    return (a.floorRange?.end ?? 0) - (b.floorRange?.end ?? 0);\n  });\n}\n\n/**\n * 优先从实时聊天记录取最新正文（保证重 roll / 从未捕获过的轮次也能拿到正解正文），\n * 仅在实时读取失败时回退到 store 缓存。\n * @returns { userText, aiText }\n */\nfunction readLiveText(aiFloor: number, userFloor: number): { userText: string; aiText: string } {\n  let aiText = '';\n  let userText = '';\n  try {\n    const aiMessages = getChatMessages ? getChatMessages(aiFloor, { role: 'assistant' }) : null;\n    if (aiMessages && aiMessages.length > 0) {\n      aiText = extractContentFromMessage(aiMessages[0].message || '') || '';\n    }\n  } catch (e) { /* 忽略，走回退 */ }\n  if (!aiText) {\n    const captured = store.capturedContents.find((c: any) => c.messageId === aiFloor);\n    aiText = captured?.content || '';\n  }\n  try {\n    const userMessages = getChatMessages ? getChatMessages(userFloor, { role: 'user' }) : null;\n    if (userMessages && userMessages.length > 0) {\n      userText = userMessages[0].message || '';\n    }\n  } catch (e) { /* 忽略，走回退 */ }\n  if (!userText) {\n    const rec = store.userInputRecords.find(\n      (r: any) => r.messageId === userFloor || r.messageId === userFloor - 1,\n    );\n    userText = rec?.userInput || '';\n  }\n  return { userText, aiText };\n}\n\n// ═══════════════════════════════════════\n// 小总结面板（从 StoryBeginTab 迁移）\n// ═══════════════════════════════════════\n\nconst PAGE_SIZE = 15;\nconst currentPage = ref(0);\n\nconst allSummaries = computed(() => {\n  const raw = store.chatData.smallSummaries || [];\n  return [...raw].reverse();\n});\n\nconst totalPages = computed(() => Math.max(1, Math.ceil(allSummaries.value.length / PAGE_SIZE)));\n\nconst pagedSummaries = computed(() => {\n  const start = currentPage.value * PAGE_SIZE;\n  return allSummaries.value.slice(start, start + PAGE_SIZE);\n});\n\nfunction prevPage() { if (currentPage.value > 0) currentPage.value--; }\nfunction nextPage() { if (currentPage.value < totalPages.value - 1) currentPage.value++; }\n\nconst expandedId = ref<string | null>(null);\nconst editingText = ref('');\nconst editingTime = ref('');\nconst editingLocation = ref('');\nconst editingChars = ref('');\n\nfunction toggleExpand(s: SmallSummaryRecord) {\n  if (expandedId.value === s.id) {\n    expandedId.value = null;\n  } else {\n    expandedId.value = s.id;\n    editingText.value = s.mainEvent || '';\n    editingTime.value = s.storyTime || '';\n    editingLocation.value = s.location || '';\n    editingChars.value = (s.presentCharacters || []).join('、');\n  }\n}\n\nfunction saveEdit(s: SmallSummaryRecord) {\n  const original = (store.chatData.smallSummaries || []).find((x: any) => x.id === s.id);\n  if (original) {\n    original.mainEvent = editingText.value;\n    original.storyTime = editingTime.value || undefined;\n    original.location = editingLocation.value || undefined;\n    original.presentCharacters = editingChars.value\n      .split(/[,，、]/).map((c: string) => c.trim()).filter(Boolean);\n    store.forcePersist();\n  }\n  expandedId.value = null;\n}\n\n// 正在重新总结的条目 id 集合（用于按钮显示\"总结中\"）\nconst retryingIds = ref<Set<string>>(new Set());\n\nfunction retrySmallSummary(s: SmallSummaryRecord) {\n  if (retryingIds.value.has(s.id)) return;\n  // 优先实时读取最新正文（重 roll 后也能拿到最新内容），实时为空再回退缓存\n  const { userText, aiText } = readLiveText(s.floorRange.end, s.floorRange.start);\n  if (!aiText) {\n    toastr?.error?.(`第 #${s.floorRange.end} 层未取到 AI 正文，无法重新总结`);\n    return;\n  }\n  retryingIds.value.add(s.id);\n  retryingIds.value = new Set(retryingIds.value);\n  enqueueAnalysis('small_summary', async () => {\n    try {\n      const allNames = store.getAllCharacterNames();\n      const newRecord = await executeSmallSummary(userText, aiText, s.floorRange.start, s.floorRange.end, allNames, store.getUserName());\n      const idx = (store.chatData.smallSummaries || []).findIndex((x: any) => x.id === s.id);\n      if (idx !== -1) {\n        store.chatData.smallSummaries[idx] = newRecord;\n      } else {\n        store.chatData.smallSummaries.push(newRecord);\n      }\n      sortSmallSummaries();\n      store.forcePersist();\n    } finally {\n      retryingIds.value.delete(s.id);\n      retryingIds.value = new Set(retryingIds.value);\n    }\n  });\n}\n\n// ─── 手动补总结：手输 AI 楼层号，补一轮（user = ai-1）的小总结 ───\nconst manualAiFloor = ref<number | null>(null);\nconst manualBusy = ref(false);\n\nfunction generateManualSummary() {\n  if (manualBusy.value) return;\n  const aiFloor = Number(manualAiFloor.value);\n  // 校验：必须是正整数，且存在于当前聊天记录范围（第0层是开场白，单独走另一入口）\n  const chatLen = (typeof SillyTavern !== 'undefined' && SillyTavern.chat?.length) || 0;\n  if (!Number.isInteger(aiFloor) || aiFloor < 1 || (chatLen > 0 && aiFloor > chatLen - 1)) {\n    toastr?.error?.('请输入有效的 AI 楼层号（正整数，在当前聊天范围内）');\n    return;\n  }\n  const userFloor = aiFloor - 1;\n  // 校验正文：AI 楼层须为 assistant，不可拿空正文去总结\n  const { userText, aiText } = readLiveText(aiFloor, userFloor);\n  if (!aiText) {\n    toastr?.error?.(`第 #${aiFloor} 层未取到 AI 正文（可能该层不是 AI 回复或内容为空），无法总结`);\n    return;\n  }\n  manualBusy.value = true;\n  console.info(`[智脑-手动补总结] #${userFloor}~#${aiFloor} AI正文${aiText.length}字 用户正文${(userText||'').length}字`);\n  enqueueAnalysis('small_summary', async () => {\n    try {\n      const allNames = store.getAllCharacterNames();\n      const record = await executeSmallSummary(userText, aiText, userFloor, aiFloor, allNames, store.getUserName());\n      // 按 floorRange 原地替换或追加（与自动流程一致）\n      const existingIdx = (store.chatData.smallSummaries || []).findIndex(\n        (ss: any) => ss.floorRange?.start === userFloor && ss.floorRange?.end === aiFloor,\n      );\n      if (existingIdx !== -1) {\n        store.chatData.smallSummaries[existingIdx] = record;\n      } else {\n        (store.chatData.smallSummaries || (store.chatData.smallSummaries = [])).push(record);\n      }\n      sortSmallSummaries();\n      store.forcePersist();\n      toastr?.success?.(`已为 #${userFloor}~#${aiFloor} 生成小总结`);\n    } catch (e: any) {\n      console.error('[智脑-手动补总结] 失败:', e);\n      toastr?.error?.('手动补总结失败: ' + (e?.message || e));\n    } finally {\n      manualBusy.value = false;\n      manualAiFloor.value = null;\n    }\n  });\n}\n\nfunction statusLabel(status: string): string {\n  const map: Record<string, string> = {\n    pending: '待生成', ready: '就绪', failed: '失败',\n    'hidden-active': '替代中', absorbed: '已吸收', ignored: '已忽略',\n  };\n  return map[status] || status;\n}\n\nfunction floorRangeText(s: SmallSummaryRecord): string {\n  return `#${s.floorRange.start}~${s.floorRange.end}`;\n}\n\n// 第0层开场白小总结\nconst hasFloorZeroSummary = computed(() =>\n  (store.chatData.smallSummaries || []).some((s: any) => s.floorRange?.start === 0 && s.floorRange?.end === 0),\n);\nconst floorZeroGenerating = ref(false);\n\nfunctio