            /* 根字号；界面大小切换 13/14/16 */\n\n  /* ── 圆角（内紧外柔） ── */\n  --zn-radius-sm:   8px;\n  --zn-radius:      12px;\n  --zn-radius-lg:   16px;\n  --zn-radius-pill: 999px;\n\n  /* ── 间距阶 ── */\n  --zn-space-1: 4px;\n  --zn-space-2: 8px;\n  --zn-space-3: 12px;\n  --zn-space-4: 16px;\n  --zn-space-5: 24px;\n  --zn-space-6: 32px;\n\n  /* ── 运动 ── */\n  --zn-ease: cubic-bezier(0.4, 0, 0.2, 1);\n  --zn-dur: 0.2s;\n  --zn-dur-fast: 0.15s;\n  --zn-dur-slow: 0.3s;\n\n  /* ── z 层级 ── */\n  --zn-z-fab: 9999;\n  --zn-z-panel: 9999;\n  --zn-z-resize: 5;\n  --zn-z-overlay: 100000;\n  --zn-z-toast: 100001;\n\n  /* ═══════════ 深色 · 夜空（默认） ═══════════ */\n  --zn-bg: #0e0b1f;                          /* 深靛紫底 */\n  --zn-glass-bg: rgba(16, 13, 34, 0.95);     /* 近实色夜空（保证文字可读，玻璃质感靠边框/高光/星光） */\n  --zn-glass-border: rgba(167, 139, 250, 0.22);\n  --zn-glass-blur: blur(10px) saturate(120%);\n  --zn-glass-highlight: inset 0 1px 0 rgba(255, 255, 255, 0.08);\n\n  /* 强调色（统一紫） */\n  --zn-accent: #a78bfa;\n  --zn-accent-rgb: 167, 139, 250;\n  --zn-accent-dim: rgba(167, 139, 250, 0.14);\n  --zn-accent-glow: rgba(167, 139, 250, 0.35);\n\n  /* 文字透明度阶梯 */\n  --zn-text-primary: rgba(255, 255, 255, 0.92);\n  --zn-text-regular: rgba(255, 255, 255, 0.70);\n  --zn-text-muted:   rgba(255, 255, 255, 0.40);\n\n  /* 表面 */\n  --zn-bg-surface1: rgba(255, 255, 255, 0.03);\n  --zn-bg-surface2: rgba(255, 255, 255, 0.06);\n  --zn-surface-sunken: rgba(0, 0, 0, 0.22);    /* 侧栏/底栏下沉重色 */\n  --zn-card-bg: #16142a;                       /* 实色卡片底（toast/弹窗） */\n\n  /* 边框 */\n  --zn-border-light: rgba(255, 255, 255, 0.08);\n  --zn-border-base:  rgba(255, 255, 255, 0.15);\n\n  /* 星光 */\n  --zn-star: rgba(255, 255, 255, 0.7);\n  --zn-star-dim: rgba(167, 139, 250, 0.55);\n\n  /* 阴影 / 光晕 */\n  --zn-shadow-glass: 0 24px 48px rgba(10, 8, 30, 0.6);\n  --zn-shadow-soft: 0 4px 16px rgba(10, 8, 30, 0.4);\n  --zn-glow-accent: 0 0 24px var(--zn-accent-glow);\n\n  /* 语义色（附 rgb 便于 rgba() 调透明度） */\n  --zn-success: #4ade80; --zn-success-rgb: 74, 222, 128;\n  --zn-warn:    #fbbf24; --zn-warn-rgb:    251, 191, 36;\n  --zn-danger:  #f87171; --zn-danger-rgb:  248, 113, 113;\n  --zn-info:    #a78bfa;\n\n  /* 兼容旧别名（旧代码用 --zn-primary 等名） */\n  --zn-primary: var(--zn-accent);\n  --zn-primary-dim: var(--zn-accent-dim);\n  --zn-text: var(--zn-text-primary);\n  --zn-text-dim: var(--zn-text-muted);\n  --zn-border: var(--zn-border-light);\n}\n\n/* ════════════════════════════════════════\n   浅色 · 白昼樱花\n   ════════════════════════════════════════ */\n.zhino-root[data-theme='light'] {\n  --zn-bg: #fdf6fb;                          /* 暖樱白 */\n  --zn-glass-bg: rgba(253, 246, 251, 0.96);  /* 近实色樱花白 */\n  --zn-glass-border: rgba(167, 139, 250, 0.28);\n  --zn-glass-highlight: inset 0 1px 0 rgba(255, 255, 255, 0.6);\n\n  --zn-accent: #8b5cf6;                      /* 加深保对比 */\n  --zn-accent-rgb: 139, 92, 246;\n  --zn-accent-dim: rgba(139, 92, 246, 0.10);\n  --zn-accent-glow: rgba(139, 92, 246, 0.25);\n\n  --zn-text-primary: #2a2440;\n  --zn-text-regular: #5a527a;\n  --zn-text-muted:   #8b85a3;\n\n  --zn-bg-surface1: rgba(139, 92, 246, 0.04);\n  --zn-bg-surface2: rgba(139, 92, 246, 0.08);\n  --zn-surface-sunken: rgba(139, 92, 246, 0.05);\n  --zn-card-bg: #ffffff;\n\n  --zn-border-light: rgba(42, 36, 64, 0.08);\n  --zn-border-base:  rgba(42, 36, 64, 0.16);\n\n  --zn-star: rgba(139, 92, 246, 0.45);\n  --zn-star-dim: rgba(255, 182, 213, 0.6);\n\n  --zn-shadow-glass: 0 24px 48px rgba(180, 160, 200, 0.28);\n  --zn-shadow-soft: 0 4px 16px rgba(180, 160, 200, 0.18);\n  --zn-glow-accent: 0 0 24px var(--zn-accent-glow);\n\n  --zn-success: #16a34a; --zn-success-rgb: 22, 163, 74;\n  --zn-warn:    #d97706; --zn-warn-rgb:    217, 119, 6;\n  --zn-danger:  #dc2626; --zn-danger-rgb:  220, 38, 38;\n  --zn-info:    #8b5cf6;\n}\n"],"sourceRoot":""}]);
